let catalogo=[],registros=[],dni="";
let itemsUbicacion=[],ubicaciones=[];

const STORAGE_KEY = "inventario_fisico_autoguardado";

document.addEventListener("DOMContentLoaded",()=>{

  catalogo = Object.entries(window.catalogoCompleto)
    .map(([c,d]) => ({ ...d, codigo: c }));

  ubicaciones = [...new Set(
    catalogo.map(i => i.ubicacion).filter(u => u)
  )];

  const dniSesion = sessionStorage.getItem("dni");
  const nombreSesion = sessionStorage.getItem("trabajador");

  if (dniSesion && nombreSesion) {

    dni = dniSesion;

    const empresaInfo = document.getElementById("empresaInfo");
    if (empresaInfo) {
      document.getElementById("empresaInfo").innerText = window.datosEmpresa.nombre;
      document.getElementById("empresaRuc").innerText = "RUC: " + window.datosEmpresa.ruc;
    }

    const dniFijo = document.getElementById("dniFijo");
    if (dniFijo) {
      dniFijo.innerText = nombreSesion;
      dniFijo.classList.add("usuario-nombre");
    }

    document.getElementById("dniBox").style.display = "none";
    document.getElementById("app").classList.remove("hidden");
  }

  cargarLocal();
});

function guardarLocal(){
  const data = {
    dni,
    registros
  };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

function cargarLocal(){
  const data = localStorage.getItem(STORAGE_KEY);
  if(!data) return;

  try{
    const obj = JSON.parse(data);

    if(obj.registros && obj.registros.length){
      registros = obj.registros;
      dni = obj.dni || "";

      const trabajador = window.trabajadores.find(t => t.dni === dni);

    if (trabajador) {
      document.getElementById("dniFijo").innerText = trabajador.nombre;
      document.getElementById("empresaInfo").innerText = window.datosEmpresa.nombre;
      document.getElementById("empresaRuc").innerText = "RUC: " + window.datosEmpresa.ruc;
    }


    if (trabajador) {
      const dniFijo = document.getElementById("dniFijo");
      dniFijo.innerText = trabajador.nombre;
      dniFijo.classList.add("usuario-nombre");
    }

    else {
      document.getElementById("dniFijo").innerText = "";
    }

      dniBox.classList.add("hidden");
      app.classList.remove("hidden");

      actualizar();
    }
  }catch(e){
    console.warn("Datos corruptos, limpiando localStorage");
    localStorage.removeItem(STORAGE_KEY);
  }
}

function cerrarSesion(){

  if (registros.length > 0) {
    alert(
      "No puede cerrar sesión.\n\n" +
      "Aún existen registros sin exportar.\n" +
      "Exporte o elimine los registros primero."
    );
    vibrar([100, 50, 100]);
    return;
  }

  sessionStorage.removeItem("dni");
  sessionStorage.removeItem("trabajador");

  dni = "";
  registros = [];

  document.getElementById("app").classList.add("hidden");
  document.getElementById("dniBox").style.display = "block";

  document.getElementById("dniInput").value = "";
  document.getElementById("dniInput").focus();
}

function actualizarBotonSesion(){
  const btn = document.getElementById("btnCerrarSesion");
  if (!btn) return;

  const bloqueado = registros.length > 0;
  btn.disabled = bloqueado;
  btn.style.opacity = bloqueado ? "0.5" : "1";
  btn.style.cursor = bloqueado ? "not-allowed" : "pointer";
}
function vibrar(patron){
  if (navigator.vibrate) {
    navigator.vibrate(patron);
  }
}

function confirmarDNI() {

  const dniIngresado = document.getElementById("dniInput").value.trim();

  const trabajador = window.trabajadores.find(
    t => t.dni === dniIngresado
  );

  if (!trabajador) {
    alert("DNI no autorizado");
    return;
  }

  dni = trabajador.dni;

  sessionStorage.setItem("dni", trabajador.dni);
  sessionStorage.setItem("trabajador", trabajador.nombre);

  document.getElementById("empresaInfo").innerText = window.datosEmpresa.nombre;
  document.getElementById("empresaRuc").innerText = "RUC: " + window.datosEmpresa.ruc;

  const dniFijo = document.getElementById("dniFijo");
  dniFijo.innerText = trabajador.nombre;
  dniFijo.classList.add("usuario-nombre");

  document.getElementById("dniBox").style.display = "none";
  document.getElementById("app").classList.remove("hidden");
}

function mostrarTab(tab,el){
  document.querySelectorAll(".tab").forEach(t=>t.classList.remove("active"));
  el.classList.add("active");
  document.querySelectorAll("[id^='tab-']").forEach(d=>d.classList.add("hidden"));
  document.getElementById("tab-"+tab).classList.remove("hidden");
}

function filtrarItems(){

  const v = codigo.value.toLowerCase();
  completarItemPorCodigo(codigo.value.trim());
  
  if (v.length < 2) {
    listaItems.classList.add("hidden");
    return;
  }

  const f = catalogo.filter(i =>
    i.codigo.toLowerCase().includes(v) ||
    i.descripcion.toLowerCase().includes(v)
  ).slice(0, 10);

  listaItems.innerHTML = f.map(i => `
    <div class="option" onmousedown="seleccionarItem('${i.codigo}')">
      ${i.codigo} - ${i.descripcion}
    </div>
  `).join("");

  listaItems.classList.remove("hidden");
}

let reconocimientoCodigo = null;

function dictarCodigo(){

  const btn = document.getElementById("btnVozCodigo");

  if(!("webkitSpeechRecognition" in window)){
    alert("Dictado por voz no compatible con este navegador");
    return;
  }

  if(!reconocimientoCodigo){
    reconocimientoCodigo = new webkitSpeechRecognition();
    reconocimientoCodigo.lang = "es-PE";
    reconocimientoCodigo.continuous = false;
    reconocimientoCodigo.interimResults = false;

    reconocimientoCodigo.onstart = () => {
      btn.classList.add("listening");
      vibrar([30]);
    };

    reconocimientoCodigo.onresult = (event) => {
      let texto = event.results[0][0].transcript;

      texto = texto
        .toUpperCase()
        .replace(/[.,;:!?]/g, "")
        .replace(/\s+/g, "")
        .replace("GUION", "-")
        .trim();

      codigo.value = texto;
      completarItemPorCodigo(texto);
      filtrarItems();
      vibrar([80]);
    };

    reconocimientoCodigo.onerror = () => {
      btn.classList.remove("listening");
    };

    reconocimientoCodigo.onend = () => {
      btn.classList.remove("listening");
    };
  }

  reconocimientoCodigo.start();
}

let reconocimientoUbicacion = null;

function dictarUbicacion(){

  const btn = document.getElementById("btnVozUbicacion");
  const input = document.getElementById("ubicacionMasiva");

  if(!("webkitSpeechRecognition" in window)){
    alert("Dictado por voz no compatible con este navegador");
    return;
  }

  if(!reconocimientoUbicacion){
    reconocimientoUbicacion = new webkitSpeechRecognition();
    reconocimientoUbicacion.lang = "es-PE";
    reconocimientoUbicacion.continuous = false;
    reconocimientoUbicacion.interimResults = false;

    reconocimientoUbicacion.onstart = () => {
      btn.classList.add("listening");
      vibrar([30]);
    };

    reconocimientoUbicacion.onresult = (event) => {
      let texto = event.results[0][0].transcript;

      texto = texto
        .toUpperCase()
        .replace(/[.,;:!?]/g, "")
        .replace(/\s+/g, "")
        .replace("GUIÓN", "-")
        .replace("GUION", "-")
        .trim();


      input.value = texto;
      filtrarUbicaciones();
      vibrar([80]);
    };

    reconocimientoUbicacion.onerror = () => {
      btn.classList.remove("listening");
    };

    reconocimientoUbicacion.onend = () => {
      btn.classList.remove("listening");
    };
  }

  reconocimientoUbicacion.start();
}

function completarItemPorCodigo(cod){
  const item = catalogo.find(i => i.codigo === cod);

  if(!item){
    descripcionItem.value = "";
    unidad.value = "";
    return;
  }

  descripcionItem.value = item.descripcion || "";
  unidad.value = item.unidad || "";
}

function seleccionarItem(c){
  const i=catalogo.find(x=>x.codigo===c);
  if(!i) return;
  
  codigo.value=i.codigo;
  descripcionItem.value = i.descripcion || "";
  ubicacion.value=i.ubicacion||"";
  cantidad.value=i.saldo??"";
  unidad.value=i.unidad||"";
 
  listaItems.classList.add("hidden");
}

function obtenerFechaHora(){
  const d = new Date();
  return {
    fecha: d.toLocaleDateString("es-PE"),
    hora: d.toLocaleTimeString("es-PE", { hour12: false })
  };
}

function guardar(){

  const cod = codigo.value.trim();
  const ubi = ubicacion.value.trim();
  const cant = Number(cantidad.value);

  if (!cod) {
    alert("Debe ingresar el Código del item");
    codigo.focus();
    return;
  }

  if (!ubi) {
    alert("Debe ingresar la Ubicación");
    ubicacion.focus();
    return;
  }

  if (isNaN(cant) || cant <= 0) {
    alert("La cantidad debe ser mayor a 0");
    cantidad.focus();
    return;
  }

const item = catalogo.find(i => i.codigo === cod);
const fh = obtenerFechaHora();

  registros.push({
    codigo: cod,
    descripcion: item ? item.descripcion : "",
    ubicacion: ubi,
    cantidad: cant,
    unidad: unidad.value,
    fecha: fh.fecha,
    hora: fh.hora,
    observaciones: obs.value.trim()
  });

const ultimoIndex = registros.length - 1;
if (esDuplicado(registros[ultimoIndex], ultimoIndex)) {
  mostrarDuplicado();
  vibrar([80, 40, 80]);
}

  codigo.value = "";
  descripcionItem.value = "";
  ubicacion.value = "";
  cantidad.value = "";
  unidad.value = "";
  obs.value = "";

  guardarLocal();
  actualizar();
}

function filtrarUbicaciones(){
  const v=ubicacionMasiva.value.toLowerCase();
  if(!v){listaUbicaciones.classList.add("hidden");return;}
  const f=ubicaciones.filter(u=>u.toLowerCase().includes(v)).slice(0,10);
  listaUbicaciones.innerHTML=f.map(u=>`
    <div class="option" onmousedown="
      ubicacionMasiva.value='${u}';
      listaUbicaciones.classList.add('hidden');
    ">${u}</div>`).join("");
  listaUbicaciones.classList.remove("hidden");
}

function cargarPorUbicacion(){

  itemsUbicacion = [];
  listaUbicacion.innerHTML = "";

  const ub = ubicacionMasiva.value.trim();
  if(!ub) return alert("Ingrese ubicación");

  itemsUbicacion = catalogo
  .filter(i => i.ubicacion === ub && Number(i.saldo) > 0)
  .sort((a, b) => Number(a.codigo) - Number(b.codigo));

  listaUbicacion.innerHTML=itemsUbicacion.map((i,idx)=>`
    <div class="registro">
      <div style="width:100%">
        <b>${i.codigo}</b> - ${i.descripcion}
        <div class="switch-box">
    <div class="cant-uni">
      <input type="number" min="0" value="${i.saldo}" id="cantU_${idx}">
      <span>${i.unidad}</span>
    </div>

    <div class="switch" id="sw_${idx}"  onclick="this.classList.toggle('active'); controlarBloqueoCargar();"></div>
    </div>

        Observaciones:
        <input id="obsU_${idx}">
      </div>
    </div>`).join("");
}

function guardarPorUbicacion(){

  for (let idx = 0; idx < itemsUbicacion.length; idx++) {

    const sw = document.getElementById(`sw_${idx}`);
    if (!sw.classList.contains("active")) continue;

    const cInput = document.getElementById(`cantU_${idx}`);
    const c = Number(cInput.value);

    if (isNaN(c) || c <= 0) {
      alert(`La cantidad debe ser mayor a 0 (Código ${itemsUbicacion[idx].codigo})`);
      cInput.focus();
      return;
    }

    const o = document.getElementById(`obsU_${idx}`).value;
    const fh = obtenerFechaHora();

    registros.push({
      codigo: itemsUbicacion[idx].codigo,
      descripcion: itemsUbicacion[idx].descripcion,
      ubicacion: itemsUbicacion[idx].ubicacion,
      cantidad: c,
      unidad: itemsUbicacion[idx].unidad,
      fecha: fh.fecha,
      hora: fh.hora,
      observaciones: o.trim()
    });

  const ultimoIndex = registros.length - 1;
  if (esDuplicado(registros[ultimoIndex], ultimoIndex)) {
  mostrarDuplicado();
  }
  }

  itemsUbicacion = [];
  listaUbicacion.innerHTML = "";
  ubicacionMasiva.value = "";

  controlarBloqueoCargar();
  guardarLocal();
  actualizar();
}

function controlarBloqueoCargar(){
  const hayActivos = document.querySelectorAll(".switch.active").length > 0;

  btnCargar.disabled = hayActivos;
  btnCargar.style.opacity = hayActivos ? "0.6" : "1";
  btnCargar.style.cursor = hayActivos ? "not-allowed" : "pointer";

  ubicacionMasiva.disabled = hayActivos;
  ubicacionMasiva.style.opacity = hayActivos ? "0.6" : "1";
  ubicacionMasiva.style.cursor = hayActivos ? "not-allowed" : "text";
}

function esDuplicado(registroActual, indiceActual){
  return registros.some((r, idx) =>
    idx !== indiceActual &&
    r.codigo === registroActual.codigo &&
    r.ubicacion === registroActual.ubicacion &&
    Number(r.cantidad) === Number(registroActual.cantidad)
  );
}

function actualizar(){
  contador.innerText = registros.length;
  actualizarBotonSesion();

  listaRegistros.innerHTML = [...registros].reverse().map((r,i)=>{
    const realIndex = registros.length - 1 - i;
    const dup = esDuplicado(r, realIndex) ? "duplicado" : "";

    return `
      <div class="registro ${dup}">
        <div style="width:100%">
          <b>${registros.length - i}. ${r.codigo}</b> - ${r.descripcion}

          <div style="
            display:flex;
            justify-content:space-between;
            align-items:center;
            margin-top:6px;
          ">
            <span>Ubicación: ${r.ubicacion}</span>

            <span style="
              color:var(--naranja);
              font-weight:600;
              min-width:90px;
              text-align:right;
            ">
              🕒 ${r.hora}
            </span>
          </div>

          <div style="margin-top:4px">
            Cantidad: ${r.cantidad} ${r.unidad}
          </div>

          ${r.observaciones ? `<small>Obs: ${r.observaciones}</small>` : ""}
        </div>

        <button class="btn-del" onclick="borrarRegistro(${realIndex})">🗑️</button>
      </div>
    `;
  }).join("");
}

function exportar(){
  if (!registros.length) {
    alert("No hay registros para exportar.");
    return;
  }

  let csv = "DNI,Código,Descripción,Ubicación,Cantidad,Unidad,Fecha,Hora,Observaciones\n";
  registros.forEach(r => {
  csv += `${dni},${r.codigo},${r.descripcion},${r.ubicacion},${r.cantidad},${r.unidad},${r.fecha},${r.hora},"${r.observaciones || ""}"\n`;
  });

  const fecha = new Date().toISOString().replace(/[:.]/g, "-");
  const nombreArchivo = `inventario_${dni}_${fecha}.csv`;

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  vibrar([100, 50, 100]);
  const url = URL.createObjectURL(blob);

  const a = document.createElement("a");
  a.href = url;
  a.download = nombreArchivo;
  document.body.appendChild(a);
  a.click();

  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  registros = [];
  localStorage.removeItem(STORAGE_KEY);
  actualizar();
}

function borrarRegistro(i){
  const r = registros[i];

  const msg =
    `¿Está seguro de eliminar el siguiente registro?\n\n` +
    `Ítem N° ${i + 1}\n` +
    `Código: ${r.codigo}\n` +
    `Ubicación: ${r.ubicacion}\n` +
    `Cantidad: ${r.cantidad} ${r.unidad}`;

  if(confirm(msg)){
    vibrar([60]);
    registros.splice(i,1);
    guardarLocal();
    actualizar();
  }
}

function mostrarDuplicado(){
  const a = document.getElementById("alertDup");
  a.classList.add("show");
  setTimeout(()=>a.classList.remove("show"),2000);
}

dniInput.addEventListener("keydown", function(e){
  if(e.key === "Enter"){
    confirmarDNI();
  }
});

window.addEventListener("beforeunload", function (e) {
  if (typeof registros !== "undefined" && registros.length > 0) {
    e.preventDefault();
    e.returnValue = "Tiene registros sin exportar. Exporte antes de salir para no perder información.";
  }
});

history.pushState(null, "", location.href);

window.addEventListener("popstate", function () {
  history.pushState(null, "", location.href);
  if (typeof registros !== "undefined" && registros.length > 0) {
    alert("Antes de salir debe exportar los registros para no perder información.");
  }
});
